import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import crypto from 'node:crypto';
const output = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../../../extension-result.json');
const result = { extensionPid:process.pid, parentPid:process.ppid, expectedSessionId:process.env.SESSION_ID ?? null, stdinIsTTY:!!process.stdin.isTTY, stdoutIsTTY:!!process.stdout.isTTY, calls:['joinSession'], phase:'loading' };
function save(){ fs.writeFileSync(output, JSON.stringify(result,null,2)); }
save();
try {
  result.sdkEntry = import.meta.resolve('@github/copilot-sdk/extension');
  const entry = fileURLToPath(result.sdkEntry);
  result.sdkEntrySha256 = crypto.createHash('sha256').update(fs.readFileSync(entry)).digest('hex');
  let dir = path.dirname(entry);
  while (dir !== path.dirname(dir)) {
    const manifest = path.join(dir,'package.json');
    if (fs.existsSync(manifest)) {
      const pkg=JSON.parse(fs.readFileSync(manifest,'utf8'));
      if(pkg.name==='@github/copilot-sdk'){result.sdkPackage={name:pkg.name,version:pkg.version,path:manifest};break;}
    }
    dir=path.dirname(dir);
  }
  result.phase='joining';save();
  const {joinSession} = await import('@github/copilot-sdk/extension');
  const session = await joinSession();
  result.joinedSessionId=session.sessionId;
  result.phase='joined';
  // Static inspection only: never invoke send or any model API.
  result.sendImplementation=typeof session.send==='function' ? Function.prototype.toString.call(session.send) : null;
  save();
} catch(error) {
  result.phase='error';result.error=String(error);save();
  process.exitCode=1;
}
